        "classifications": {},
        "rcrit_estimates": {},
        "summary": {}
    }

    print("=" * 80)
    print("r_crit(T) Sensitivity Analysis")
    print("=" * 80)

    # Classification matrix
    print(f"\n{'r':<6}", end="")
    for T in T_values:
        print(f"{'T='+str(T):<20}", end="")
    print()
    print("-" * 80)

    for r in r_values:
        seeds = DATA[r]
        print(f"{r:<6}", end="")
        results["classifications"][str(r)] = {}

        for T in T_values:
            seed_types = {}
            for seed_name, traj in seeds.items():
                truncated = traj[:T+1]
                ttype = classify_trajectory(truncated)
                seed_types[seed_name] = ttype

            types_list = list(seed_types.values())
