        print()

    # r_crit estimation per T
    print(f"\n{'=' * 80}")
    print("r_crit(T) Estimation")
    print("=" * 80)

    for T in T_values:
        # Find boundary between Type II and Type III
        # r_crit = smallest r where trajectory is Type III (no transient dip)
        type_by_r = {}
        for r in r_values:
            seeds = DATA[r]
            types = []
            for seed_name, traj in seeds.items():
                truncated = traj[:T+1]
                types.append(classify_trajectory(truncated))
            type_by_r[r] = max(set(types), key=types.count)

        # Find transition from II to III
        rcrit_lower = None
        rcrit_upper = None
        for i, r in enumerate(r_values):
