                    rcrit_upper = r
                    rcrit_lower = r_values[i-1] if type_by_r[r_values[i-1]] != "III" else (r_values[i-2] if i >= 2 else 0.0)

        if rcrit_lower is not None and rcrit_upper is not None:
            est = f"({rcrit_lower}, {rcrit_upper}]"
        elif all(t == "III" for t in type_by_r.values() if t != "I"):
            est = "≤ min tested r (all III except r=0)"
        else:
            est = "not clearly identifiable"

        results["rcrit_estimates"][str(T)] = {
            "range": est,
            "type_by_r": {str(k): v for k, v in type_by_r.items()}
        }
        print(f"T={T:<3}: r_crit ∈ {est}  |  Types: {type_by_r}")

    # Stability conclusion
    print(f"\n{'=' * 80}")
    print("Stability Analysis")
    print("=" * 80)

    # Check if classifications are consistent across T
    inconsistent = []
    for r in r_values:
        types_across_T = []
        for T in T_values:
            cls = results["classifications"][str(r)][str(T)]
            types_across_T.append(cls["majority_type"])
        if len(set(types_across_T)) > 1:
            inconsistent.append((r, types_across_T))

    if inconsistent:
        print(f"\nInconsistent classifications across T:")
        for r, types in inconsistent:
            print(f"  r={r}: {dict(zip(T_values, types))}")
    else:
        print(f"\nAll classifications consistent across T={T_values}")

    # Detailed analysis of boundary cases
    print(f"\n--- Boundary case detail (r=0.2, r=0.25) ---")
    for r in [0.2, 0.25]:
        print(f"\nr={r}:")
        for seed_name, traj in DATA[r].items():
            print(f"  {seed_name}: ", end="")
