def classify_trajectory(slv, noise_tol=0.005):
    """
    Classify a truncated SLV trajectory.

    Type I:  SLV reaches peak then sustains decline (2+ gens declining, SLV_T < SLV_peak)
    Type II: SLV has transient dip(s) but SLV_T > SLV_0
    Type III: SLV monotonically non-decreasing (within noise tolerance)
    """
    slv = np.array(slv)
    T = len(slv) - 1  # number of generations (index 0 = gen 0)

    if T < 2:
        return "III"  # too short to classify

    # Check Type I: find peak, then sustained decline
    peak_idx = np.argmax(slv)
    if peak_idx < T:
        # Check if decline is sustained (at least 2 consecutive drops after peak)
        post_peak = slv[peak_idx:]
        if len(post_peak) >= 3:
            declines = np.diff(post_peak) < 0
            # Need at least 2 consecutive declines
            consecutive_declines = 0
            max_consecutive = 0
            for d in declines:
                if d:
                    consecutive_declines += 1
                    max_consecutive = max(max_consecutive, consecutive_declines)
                else:
                    consecutive_declines = 0
            if max_consecutive >= 2 and slv[T] < slv[peak_idx]:
                return "I"

    # Check Type III: monotonically non-decreasing (within noise)
    diffs = np.diff(slv)
    rel_diffs = diffs / slv[:-1]
    if np.all(rel_diffs >= -noise_tol):
        return "III"

    # Type II: has dip(s) but ends above start
    if slv[T] > slv[0]:
        return "II"

    # Fallback: if ends below start with dips but no sustained decline pattern
    return "I"


